import os
import binascii
from google.cloud import kms_v1
from security_client import KmsClient
from security_models import EnvelopeEncryptionRequest, EnvelopeEncryptionResponse


def envelope_encrypt(request: EnvelopeEncryptionRequest) -> EnvelopeEncryptionResponse:
    client = KmsClient().get_client()
    key_name = request.key_name
    plaintext_bytes = request.plaintext.encode("utf-8")

    try:
        # Perform symmetric encryption with a new data key generated by KMS
        # The data key is encrypted by the master key in KMS
        response = client.encrypt_symmetric(
            request={"name": key_name, "plaintext": plaintext_bytes}
        )

        return EnvelopeEncryptionResponse(
            encrypted_data_key=response.encrypted_data_key.hex(),
            ciphertext=response.ciphertext.hex(),
            key_name=key_name,
        )
    except Exception as e:
        raise RuntimeError(
            f"Failed to perform envelope encryption with Google Cloud KMS: {e}"
        )
